import { test, expect } from '@playwright/test';

test.describe('Live Data Last Updated Timestamp', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/live-data');
  });

  test('should display the last updated timestamp for live data', async ({ page }) => {
    // Verify the live data table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify the last updated timestamp is displayed
    const timestamp = page.getByText('Last Updated: 2023-04-01 12:34:56');
    await expect(timestamp).toBeVisible();

    // Verify the timestamp is formatted correctly
    const timestampText = page.getByText('Last Updated: 2023-04-01 12:34:56');
    await expect(timestampText).toContainText('2023-04-01');
    await expect(timestampText).toContainText('12:34');

    // Verify the timestamp is clickable and navigates to a detailed view
    await expect(timestamp).toBeClickable();
    const detailView = page.getByRole('region', { name: /live data details/i });
    await expect(detailView).toBeVisible();

    // Verify the detail view contains more information
    const detailTitle = page.getByText('Live Data Details');
    await expect(detailTitle).toBeVisible();

    // Verify the detail view has a refresh button
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await expect(refreshButton).toBeVisible();

    // Verify the refresh button is clickable
    await expect(refreshButton).toBeClickable();
  });

  test('should handle empty live data with no timestamp', async ({ page }) => {
    // Verify the live data table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify the last updated timestamp is not displayed
    const timestamp = page.getByText('Last Updated: 2023-04-01 12:34:56');
    await expect(timestamp).not.toBeVisible();

    // Verify the table has a loading state
    const loadingState = page.getByText('Loading...');
    await expect(loadingState).toBeVisible();

    // Verify the table has no data rows
    const dataRows = page.getByRole('row');
    await expect(dataRows).not.toBeVisible();

    // Verify the table has a no data message
    const noDataMessage = page.getByText('No live data available');
    await expect(noDataMessage).toBeVisible();

    // Verify the refresh button is visible and clickable
    const refreshButton = page.getByRole('button', { name: /refresh/i });
    await expect(refreshButton).toBeVisible();
    await expect(refreshButton).toBeClickable();
  });
});
